// @name 2048
// @background #f6f1e9
// @refresh 3600
// 2048: slide the tiles, equal tiles merge, reach 2048. Swipe on the board,
// tap the arrow buttons (made for e-paper, where a swipe is one refresh like a
// tap; a frame's keys walk them), use the arrow keys on a keyboard, or tip the
// frame that way where it has an accelerometer (a `tilt`, or a quick `flick`
// of the wrist: the reTerminal Sticky, the round AMOLED). One
// undo, the best score per board size, and the game in progress are kept in
// the scene's state, so they outlast a restart.
import { biggest, isOver, move, newGame, readGame, undo } from './logic'

// What a move changes is in signals: a tap runs only the cells, the numbers
// and the Undo button that read them, not get(). The game shown and its app
// are kept for the handlers, which change them.
const cells = []
const cellAt = (i: number) => cells[i] || (cells[i] = signal(0))
const score = signal(0)
const best = signal(0)
const canUndo = signal(false)
let game = null
let gameApp = null
// The card over the board ('confirm', 'win', 'over' or ''): get() draws it,
// so a change while one shows, comes or goes sets no signal and get() runs.
let cardShown = ''
const cardOf = (g, confirm: boolean) => (confirm ? 'confirm' : g.won && !g.keepPlaying ? 'win' : isOver(g) ? 'over' : '')

const show = (g, confirm: boolean) => {
  for (let i = 0; i < g.cells.length; i++) cellAt(i).value = g.cells[i]
  score.value = g.score
  best.value = g.best
  canUndo.value = !!g.undo && !confirm
}

// The game changed: into the signals, unless a card shows before or after.
const shown = (next) => {
  const was = cardShown
  game = next
  cardShown = cardOf(next, !!frameos.recall('confirm'))
  if (!was && !cardShown) show(next, false)
}

// High contrast where the panel shows no color (black and white, greys), or
// when the scene's Contrast setting asks for it.
const highContrast = (app) => {
  const mode = app.state.contrast || 'auto'
  return mode === 'high' || (mode === 'auto' && app.frame.color === false)
}
// Color e-paper (a Spectra panel's six inks) on Auto: a white page, black
// ink and solid colors only, since the sand and pastel tones dither to confetti.
const inkPaper = (app) => (app.state.contrast || 'auto') === 'auto' && app.frame.paper === true && app.frame.color !== false

const THEMES = {
  color: {
    page: 'bg-[#f6f1e9] text-[#3b3631]',
    muted: 'text-[#8a7f72]',
    title: 'text-[#b4532f]',
    board: 'bg-[#bfb3a3]',
    empty: 'bg-[#d8cdbf]',
    stat: 'bg-[#3e4a59] text-white',
    statLabel: 'text-[#c9d2dc]',
    arrow: 'bg-[#2f6b66] text-white active:bg-[#24524e]',
    button: 'bg-[#e5dccf] text-[#3b3631] active:bg-[#d6cab9]',
    buttonOff: 'bg-[#ece6dc] text-[#b5aa9c]',
    primary: 'bg-[#b4532f] text-white active:bg-[#923f22]',
    card: 'bg-[#fbf8f3] border-4 border-[#3e4a59] text-[#3b3631]',
  },
  high: {
    page: 'bg-white text-black',
    muted: 'text-black',
    title: 'text-black',
    board: 'bg-white border-4 border-black',
    empty: 'bg-white',
    stat: 'bg-white text-black border-2 border-black',
    statLabel: 'text-black',
    arrow: 'bg-black text-white',
    button: 'bg-white text-black border-2 border-black',
    // Undo with nothing to take back: a thin frame and the word struck
    // through, never a grey that dithers away.
    buttonOff: 'bg-white text-black border border-black font-normal line-through',
    primary: 'bg-black text-white',
    card: 'bg-white border-4 border-black text-black',
  },
  // Color e-paper: the board and its empty cells white with black outlines,
  // the tiles in the panel's solid inks.
  ink: {
    page: 'bg-white text-black',
    muted: 'text-black',
    title: 'text-[#cc0000]',
    board: 'bg-white border-4 border-black',
    empty: 'bg-white border-2 border-black',
    stat: 'bg-white text-black border-2 border-black',
    statLabel: 'text-black',
    arrow: 'bg-[#0033cc] text-white',
    button: 'bg-white text-black border-2 border-black',
    buttonOff: 'bg-white text-black border border-black font-normal line-through',
    primary: 'bg-[#cc0000] text-white',
    card: 'bg-white border-4 border-black text-black',
  },
}

// Tile colors on color e-paper: one ink a value up to 64, then the same inks
// again with a ring inside from 128.
const INK_TILES = [
  ['#ffffff', '#000000'],
  ['#ffff00', '#000000'],
  ['#cc0000', '#ffffff'],
  ['#006b2e', '#ffffff'],
  ['#0033cc', '#ffffff'],
  ['#000000', '#ffffff'],
]

// Tile colors in color mode: warm sand to terracotta, then sage, teal and
// navy for the big ones, so every value has a tone of its own.
const TILE_COLORS = {
  2: ['#f3ede3', '#5b5147'],
  4: ['#ece0c6', '#5b5147'],
  8: ['#e9b67c', '#ffffff'],
  16: ['#e19659', '#ffffff'],
  32: ['#d5744a', '#ffffff'],
  64: ['#b9523a', '#ffffff'],
  128: ['#8fb28f', '#ffffff'],
  256: ['#6b9a7e', '#ffffff'],
  512: ['#3f7d6f', '#ffffff'],
  1024: ['#2f6a80', '#ffffff'],
  2048: ['#e2b63f', '#ffffff'],
}
const BIG_TILE = ['#3a2f52', '#ffffff']

const sizeSetting = (app) => {
  const n = parseInt(app.state.size, 10)
  return n === 5 || n === 6 ? n : 4
}

const loadBests = (app) => {
  const kept = app.state.best
  return kept && typeof kept === 'object' && !Array.isArray(kept) ? kept : {}
}

/** The game in progress, or a new one when there is none or the board size setting changed. */
const loadGame = (app) => {
  const size = sizeSetting(app)
  const kept = readGame(app.state.game)
  if (kept && kept.size === size) return kept
  const game = newGame(size, Date.now() % 2147483647, Number(loadBests(app)[size]) || 0)
  save(app, game)
  return game
}

const save = (app, game) => {
  frameos.setState('game', game)
  const bests = loadBests(app)
  if ((Number(bests[game.size]) || 0) < game.best) frameos.setState('best', { ...bests, [game.size]: game.best })
}

// Every change goes through here: a copy of the game, changed, then saved and shown.
const change = (app, fn: (g) => boolean | void) => {
  const copy = readGame(JSON.parse(JSON.stringify(game)))
  if (fn(copy) === false) return false
  save(app, copy)
  shown(copy)
  return true
}

const startOver = (app) => {
  frameos.remember('confirm', false)
  const next = newGame(game.size, (Date.now() ^ (game.seed * 7919)) % 2147483647, game.best)
  save(app, next)
  shown(next)
}

/** "New game" asks first while a game is under way; a finished or untouched one starts over at once. */
const askNewGame = (app) => {
  if (game.moves === 0 || isOver(game) || (game.won && !game.keepPlaying)) startOver(app)
  else frameos.remember('confirm', true)
}

const play = (app, dir) => {
  if (frameos.recall('confirm')) return false
  return change(app, (g) => move(g, dir))
}

// Arrow keys (and WASD) on a keyboard. The frame's back closes the "New
// game?" card and is otherwise the frame's, never a move: on a board without
// a touch screen it is the Back key. A frame's own keys (a reTerminal's LEFT
// and RIGHT, a Sticky's UP and DOWN) walk the buttons on the screen and press
// them: taken as moves by their names, they left two of the four directions
// out of reach on a frame with nothing else to press.
const KEYS = {
  ArrowLeft: 'left', ArrowRight: 'right', ArrowUp: 'up', ArrowDown: 'down',
  a: 'left', d: 'right', w: 'up', s: 'down', h: 'left', l: 'right', k: 'up', j: 'down',
}

export function onEvent(app, context) {
  game = loadGame(app)
  const p = context.payload || {}
  if (context.event === 'back') {
    if (!frameos.recall('confirm')) return false
    frameos.remember('confirm', false)
    return true
  }
  if (context.event === 'tilt' || context.event === 'flick') {
    // The frame tipped towards a side of the picture: the tiles slide there.
    // A card over the board waits for a tap.
    const dir = p.direction
    if (dir !== 'left' && dir !== 'right' && dir !== 'up' && dir !== 'down') return false
    return play(app, dir)
  }
  if (context.event === 'keyDown') {
    if (p.ctrl || p.alt || p.meta) return false
    const key = String(p.key || '')
    if (frameos.recall('confirm')) {
      if (key === 'Enter' || key === 'y') startOver(app)
      else if (key === 'Escape' || key === 'n') frameos.remember('confirm', false)
      else return false
      return true
    }
    const dir = KEYS[key] || KEYS[key.toLowerCase()]
    if (dir) return play(app, dir)
    if (key === 'u' || key === 'Backspace' || (key === 'z' && p.ctrl)) return change(app, (g) => undo(g))
    if (key === 'n') {
      askNewGame(app)
      return true
    }
  }
  return false
}

// An arrow pointing right, turned for the other directions.
const ARROW = 'M8.6 5.4 15.2 12l-6.6 6.6L7 17l5-5-5-5z'
const TURN = { right: 0, down: 90, left: 180, up: 270 }
const Arrow = ({ dir, px }) => (
  <svg viewBox="0 0 24 24" className={`w-[${px}px] h-[${px}px]`}>
    <g transform={`rotate(${TURN[dir]} 12 12)`}>
      <path d={ARROW} fill="currentColor" />
    </g>
  </svg>
)

// One tile. In high contrast the value is told by the tile's look as well as
// its number: thin to thick borders for the small ones, black for 32 and up,
// with one or two white rings inside from 128 and 1024.
const Tile = ({ value, px, hc, ink, empty }) => {
  if (!value && hc) {
    // An empty cell on a white board: a small dot, so the grid still reads.
    const dot = Math.max(4, Math.round(px * 0.08))
    return (
      <div className={`w-[${px}px] h-[${px}px] flex items-center justify-center`}>
        <div className={`w-[${dot}px] h-[${dot}px] rounded-full bg-black`} />
      </div>
    )
  }
  if (!value) return <div className={`w-[${px}px] h-[${px}px] rounded-[${Math.round(px * 0.08)}px] ${empty}`} />
  const digits = String(value).length
  const font = Math.round(px * (digits <= 2 ? 0.46 : digits === 3 ? 0.38 : digits === 4 ? 0.3 : 0.24))
  const radius = Math.round(px * 0.08)
  const text = `text-[${font}px] font-bold leading-none`
  if (ink) {
    const level = Math.round(Math.log2(value))
    const [bg, fg] = INK_TILES[(level - 1) % 6]
    const edge = level === 1 ? 'border-2 border-black' : ''
    if (level < 7) {
      return (
        <div className={`w-[${px}px] h-[${px}px] rounded-[${radius}px] flex items-center justify-center bg-[${bg}] text-[${fg}] ${edge} ${text}`}>
          {value}
        </div>
      )
    }
    const inset = Math.max(3, Math.round(px * 0.06))
    return (
      <div className={`w-[${px}px] h-[${px}px] rounded-[${radius}px] flex bg-[${bg}] ${level === 7 ? 'border-2 border-black' : ''}`}>
        <div className={`flex-1 flex m-[${inset}px] border-2 border-[${fg}] rounded-[${Math.max(2, radius - 2)}px] items-center justify-center text-[${fg}] ${text}`}>{value}</div>
      </div>
    )
  }
  if (!hc) {
    const [bg, fg] = TILE_COLORS[value] || BIG_TILE
    return (
      <div className={`w-[${px}px] h-[${px}px] rounded-[${radius}px] flex items-center justify-center bg-[${bg}] text-[${fg}] ${text}`}>
        {value}
      </div>
    )
  }
  const level = Math.round(Math.log2(value))
  if (level < 5) {
    const border = [2, 2, 4, 6, 9][level]
    return (
      <div className={`w-[${px}px] h-[${px}px] rounded-[${radius}px] flex items-center justify-center bg-white text-black border-[${border}px] border-black ${text}`}>
        {value}
      </div>
    )
  }
  const rings = level >= 10 ? 2 : level >= 7 ? 1 : 0
  const inset = Math.max(3, Math.round(px * 0.06))
  let inner = <div className={`flex-1 flex items-center justify-center ${text} text-white`}>{value}</div>
  for (let r = 0; r < rings; r++) {
    inner = <div className={`flex-1 flex m-[${inset}px] border-2 border-white rounded-[${Math.max(2, radius - 2)}px]`}>{inner}</div>
  }
  return <div className={`w-[${px}px] h-[${px}px] rounded-[${radius}px] flex bg-black`}>{inner}</div>
}

const Cell = memo(({ i, px, hc, ink, empty }) => <Tile value={cellAt(i).value} px={px} hc={hc} ink={ink} empty={empty} />)

// "Score" or "Best".
const Stat = memo(({ label, t, w, h, font }) => (
  <div className={`flex flex-col items-center justify-center rounded-xl w-[${w}px] h-[${h}px] ${t.stat}`}>
    <span className={`text-[${Math.max(10, Math.round(font * 0.45))}px] uppercase font-bold ${t.statLabel}`}>{label}</span>
    <span className={`text-[${font}px] font-bold leading-none`}>{(label === 'Best' ? best : score).value}</span>
  </div>
))

// On a round panel the score and best share one line in the arc above the board.
const RoundStats = memo(({ font, t }) => (
  <div className={`flex items-baseline gap-[${Math.round(font * 0.7)}px] text-[${font}px] leading-none`}>
    <span className={`font-black ${t.title}`}>2048</span>
    <span className={t.muted}>Score</span>
    <span className="font-bold">{score.value}</span>
    <span className={t.muted}>Best</span>
    <span className="font-bold">{best.value}</span>
  </div>
))

// A round panel (only the circle inside the square shows): the board fills
// the square inside the circle, the numbers go in the arc above it and the
// buttons in the arc below, each row as wide as the circle is there.
const roundRoom = (W: number, H: number) => {
  const r = Math.min(W, H) / 2
  const side = Math.floor((r - 12) * Math.SQRT2)
  const y0 = (H - side) >> 1
  // How wide a row may be whose far edge is dy px from the centre.
  const chord = (dy: number) => Math.floor(2 * Math.sqrt(Math.max(0, (r - 12) * (r - 12) - dy * dy)))
  return { side, y0, arc: y0, chord }
}

const UndoButton = memo(({ w, h, font, t }) => (
  <div className={`w-[${w}px] h-[${h}px] rounded-xl flex items-center justify-center text-[${font}px] font-bold ${canUndo.value ? t.button : t.buttonOff}`}
    onClick={() => change(gameApp, (g) => undo(g))}>
    Undo
  </div>
))

export function get(app, context) {
  const W = context.imageWidth ?? app.frame.width
  const H = context.imageHeight ?? app.frame.height
  const round = context.round === true
  const hc = highContrast(app)
  const ink = !hc && inkPaper(app)
  const t = hc ? THEMES.high : ink ? THEMES.ink : THEMES.color
  game = loadGame(app)
  gameApp = app
  const confirm = !!frameos.recall('confirm')
  cardShown = cardOf(game, confirm)
  show(game, confirm)
  const over = isOver(game)
  const showWin = game.won && !game.keepPlaying

  const m = Math.round(Math.min(W, H) * 0.04)
  const wide = W >= H * 1.25
  // Wide screens put the board left and the controls right; anything else stacks them.
  // A tall screen has room for two rows of controls under the board: the
  // arrows, then Undo and New game. A screen too narrow for the six in one row
  // (a watch) puts Undo and New beside the numbers over the board instead.
  const tall = !wide && H >= W * 1.3
  const compact = !wide && !tall && W - 2 * m < 6 * 48 + 5 * 8
  const headerH = wide ? 0 : compact ? Math.round(Math.max(40, Math.min(H * 0.15, 56))) : Math.round(Math.max(56, H * 0.11))
  const tallKey = Math.round(Math.max(52, Math.min(H * 0.085, 110)))
  const compactKey = Math.round(Math.max(36, Math.min(H * 0.135, 52)))
  const padH = wide ? 0 : tall ? tallKey * 2 + 10 : compact ? compactKey : Math.round(Math.max(52, Math.min(H * 0.11, 96)))
  // Between the buttons beside the board: 10 px, less on a small screen; and
  // beside the board there is always room for arrows of at least 36 px.
  const g = Math.round(Math.max(6, Math.min(10, Math.min(W, H) * 0.025)))
  const minKey = 36
  const board = round ? roundRoom(W, H).side : Math.floor(wide ? Math.min(H - 2 * m, (W - 3 * m) * 0.64, W - 3 * m - 3 * minKey - 2 * g) : Math.min(W - 2 * m, H - headerH - padH - 4 * m))
  const n = game.size
  const gap = Math.max(4, Math.round(board * (n >= 6 ? 0.018 : 0.025)))
  const tile = Math.floor((board - gap * (n + 1)) / n)
  const boardPx = tile * n + gap * (n + 1)

  // Beside the board: the title, the numbers, the arrows in a cross and Undo
  // / New game, one under the other, the arrows as big as the column's height
  // and width allow. Where that leaves them under 36 px, a short strip with
  // room across puts the arrows beside the rest ('split'), and a small screen
  // stacks the arrows as an inverted T ('small').
  const panelW = wide ? W - boardPx - 3 * m : W - 2 * m
  const colH = H - 2 * m
  const statFont = Math.round(Math.max(18, Math.min(wide ? Math.min(panelW * 0.09, colH * 0.13) : headerH * 0.42, Math.max(40, Math.min(W, H) * 0.045))))
  const titleF = Math.round(Math.min(panelW * 0.22, H * 0.14))
  const statH = Math.round(Math.max(Math.min(56, colH * 0.2), statFont * 2.1))
  const keyFit = (panelW - 2 * g) / 3
  const wideKey = Math.max(48, Math.min(keyFit, colH * 0.16))
  const columnKey = Math.round(Math.min(wideKey, keyFit, (colH - titleF - statH - 2 * g - 12) / 4))
  const side = !wide || columnKey >= minKey ? 'column' : panelW >= 3 * 48 + 2 * g + 160 + m ? 'split' : 'small'

  // Buttons: at least 48 px, more on a bigger screen.
  const key = tall ? tallKey : compact ? compactKey : wide
    ? side === 'column' ? columnKey : side === 'split' ? Math.round(Math.min(wideKey, (colH - 2 * g) / 3)) : Math.floor(Math.min(keyFit, (colH - statH - g - 12) / 3))
    : Math.round(Math.max(48, Math.min((panelW - 5 * 8) / 6, padH)))
  // "New game" has to fit in half the panel (or in its button when stacked).
  const font = Math.round(Math.max(16, Math.min(key * 0.3, 44, wide ? (panelW / 2 - 24) / 5 : 44)))

  const rows = []
  for (let y = 0; y < n; y++) {
    rows.push(
      <div className={`flex gap-[${gap}px]`}>
        {game.cells.slice(y * n, y * n + n).map((_, x) => (
          <Cell i={y * n + x} px={tile} hc={hc} ink={ink} empty={t.empty} />
        ))}
      </div>,
    )
  }

  // A message over the board: solid, not see-through, so e-paper draws it
  // clean. On a small board it sits higher, in smaller type, and its buttons
  // go one under the other when the two do not fit side by side; under 200 px
  // the line under the title goes (the score shows beside the board anyway).
  const small = boardPx < 260
  const inset = Math.round(boardPx * 0.06)
  const cardPad = Math.round(boardPx * 0.045)
  const cardFont = Math.round(Math.max(small ? 14 : 16, Math.min(font, boardPx * 0.05)))
  const cardButtonH = small ? Math.max(34, Math.round(boardPx * 0.15)) : Math.max(48, Math.round(boardPx * 0.12))
  const cardRoom = boardPx - 2 * inset - 2 * cardPad - 8
  const card = (title: string, line: string, labels: string[], buttons) => {
    const across = labels.reduce((w, label) => w + label.length * 0.62 * cardFont + 32, 12 * (labels.length - 1)) <= cardRoom
    return (
      <div className={`absolute left-[${inset}px] right-[${inset}px] top-[${Math.round(boardPx * (small ? 0.08 : 0.22))}px] rounded-2xl p-[${cardPad}px] flex flex-col items-center ${small ? 'gap-2' : 'gap-3'} ${t.card}`}>
        <span className={`text-[${Math.round(Math.max(small ? 15 : 0, boardPx * 0.085))}px] font-bold text-center`}>{title}</span>
        {boardPx >= 200 ? <span className={`text-[${Math.round(Math.max(small ? 13 : 16, boardPx * 0.042))}px] text-center`}>{line}</span> : null}
        <div className={across ? 'flex gap-3' : 'flex flex-col gap-2 w-full'}>{buttons}</div>
      </div>
    )
  }
  const cardButton = (label: string, cls: string, onClick) => (
    <div className={`h-[${cardButtonH}px] px-4 rounded-xl flex items-center justify-center whitespace-nowrap text-[${cardFont}px] font-bold ${cls}`} onClick={onClick}>
      {label}
    </div>
  )

  let overlay = null
  if (confirm) {
    overlay = card('New game?', game.score ? `This game's score of ${game.score} will be lost.` : 'The game in progress will be lost.', ['Cancel', 'New game'], [
      cardButton('Cancel', t.button, () => frameos.remember('confirm', false)),
      cardButton('New game', t.primary, () => startOver(app)),
    ])
  } else if (showWin) {
    overlay = card('You made 2048!', `Score ${game.score} in ${game.moves} moves.`, ['Keep playing', 'New game'], [
      cardButton('Keep playing', t.primary, () => change(app, (g) => { g.keepPlaying = true })),
      cardButton('New game', t.button, () => startOver(app)),
    ])
  } else if (over) {
    overlay = card('No moves left', `Score ${game.score}, biggest tile ${biggest(game)}.`, ['Undo', 'New game'], [
      cardButton('Undo', t.button, () => change(app, (g) => undo(g))),
      cardButton('New game', t.primary, () => startOver(app)),
    ])
  }

  const boardBox = (
    <div className={`relative w-[${boardPx}px] h-[${boardPx}px] shrink-0 rounded-[${Math.round(gap * 1.5)}px] p-[${gap}px] flex flex-col gap-[${gap}px] ${t.board}`}
      onSwipe={(e) => play(app, e.direction)}>
      {rows}
      {overlay}
    </div>
  )

  const arrowButton = (dir, w = key) => (
    <div className={`w-[${w}px] h-[${key}px] rounded-xl flex items-center justify-center ${t.arrow}`} onClick={() => play(app, dir)}>
      <Arrow dir={dir} px={Math.round(key * 0.62)} />
    </div>
  )
  const undoButton = (w: number, h = key, f = font) => <UndoButton w={w} h={h} font={f} t={t} />
  const newButton = (w: number, label: string, h = key, f = font) => (
    <div className={`w-[${w}px] h-[${h}px] rounded-xl flex items-center justify-center text-[${f}px] font-bold ${t.primary}`}
      onClick={() => askNewGame(app)}>
      {label}
    </div>
  )
  // "New game" where it fits its button, else "New".
  const newLabel = (w: number, f = font) => (4.96 * f + 16 <= w ? 'New game' : 'New')

  if (round) {
    const { arc, chord } = roundRoom(W, H)
    const top = (H - boardPx) >> 1
    const statFont = Math.max(14, Math.min(28, Math.round(arc * 0.24)))
    const bh = Math.max(36, Math.round(arc * 0.52))
    const bTop = top + boardPx + Math.max(6, Math.round(arc * 0.1))
    const bw = Math.floor((chord(bTop + bh - H / 2) - 10) / 2)
    const bFont = Math.max(14, Math.min(font, Math.round(bh * 0.42)))
    return (
      <div className={`relative w-[${W}px] h-[${H}px] ${t.page}`}>
        <div className={`absolute left-0 top-0 w-[${W}px] h-[${top - Math.max(6, Math.round(arc * 0.12))}px] flex items-end justify-center`}>
          <RoundStats font={statFont} t={t} />
        </div>
        <div className={`absolute left-[${(W - boardPx) >> 1}px] top-[${top}px]`}>{boardBox}</div>
        <div className={`absolute left-0 top-[${bTop}px] w-[${W}px] flex justify-center gap-[10px]`}>
          <UndoButton w={bw} h={bh} font={bFont} t={t} />
          <div className={`w-[${bw}px] h-[${bh}px] rounded-xl flex items-center justify-center text-[${bFont}px] font-bold ${t.primary}`}
            onClick={() => askNewGame(app)}>
            New
          </div>
        </div>
      </div>
    )
  }

  if (wide) {
    const half = Math.floor((panelW - 12) / 2)
    const title = (w: number) => (
      <div className={`flex w-[${w}px] items-end justify-between`}>
        <span className={`text-[${titleF}px] font-black leading-none ${t.title}`}>2048</span>
        <span className={`text-[${Math.round(font * 0.8)}px] ${t.muted}`}>{`${n}×${n}`}</span>
      </div>
    )
    const stats = (w: number) => (
      <div className={`flex w-[${w}px] justify-between`}>
        <Stat label="Score" t={t} w={Math.floor((w - 12) / 2)} h={statH} font={statFont} />
        <Stat label="Best" t={t} w={Math.floor((w - 12) / 2)} h={statH} font={statFont} />
      </div>
    )
    const buttons = (w: number) => {
      const bw = Math.floor((w - 12) / 2)
      return (
        <div className={`flex w-[${w}px] justify-between`}>
          {undoButton(bw)}
          {newButton(bw, newLabel(bw))}
        </div>
      )
    }
    const cross = (
      <div className={`flex flex-col items-center gap-[${g}px]`}>
        {arrowButton('up')}
        <div className={`flex gap-[${g}px]`}>
          {arrowButton('left')}
          <div className={`w-[${key}px] h-[${key}px]`} />
          {arrowButton('right')}
        </div>
        {arrowButton('down')}
      </div>
    )
    if (side === 'split') {
      // A short strip: the arrows to the right of the title, the numbers and the buttons.
      const crossW = 3 * key + 2 * g
      const restW = panelW - crossW - m
      return (
        <div className={`flex w-full h-full p-[${m}px] gap-[${m}px] items-center ${t.page}`}>
          {boardBox}
          <div className={`w-[${restW}px] h-full flex flex-col justify-between`}>
            {title(restW)}
            {stats(restW)}
            {buttons(restW)}
          </div>
          {cross}
        </div>
      )
    }
    if (side === 'small') {
      // A small screen: the arrows as an inverted T, the title only where it fits.
      const titled = titleF + statH + 3 * key + 3 * g + 16 <= colH
      return (
        <div className={`flex w-full h-full p-[${m}px] gap-[${m}px] items-center ${t.page}`}>
          {boardBox}
          <div className="flex-1 h-full flex flex-col justify-between">
            {titled ? title(panelW) : null}
            {stats(panelW)}
            <div className={`flex flex-col items-center gap-[${g}px]`}>
              {arrowButton('up')}
              <div className={`flex gap-[${g}px]`}>
                {arrowButton('left')}
                {arrowButton('down')}
                {arrowButton('right')}
              </div>
            </div>
            {buttons(panelW)}
          </div>
        </div>
      )
    }
    return (
      <div className={`flex w-full h-full p-[${m}px] gap-[${m}px] items-center ${t.page}`}>
        {boardBox}
        <div className="flex-1 h-full flex flex-col justify-between">
          {title(panelW)}
          {stats(panelW)}
          {cross}
          {buttons(panelW)}
        </div>
      </div>
    )
  }

  if (compact) {
    // A small screen (a watch): Undo and New beside the numbers over the
    // board, the four arrows under it, both rows as wide as the screen.
    const w = W - 2 * m
    const statW = Math.floor((w - 3 * g) * 0.28)
    const bw = Math.floor((w - 3 * g - 2 * statW) / 2)
    const bFont = Math.round(Math.max(13, Math.min(font, (bw - 8) / 2.6, headerH * 0.38)))
    const aw = Math.floor((w - 3 * g) / 4)
    return (
      <div className={`flex flex-col w-full h-full p-[${m}px] gap-[${m}px] items-center justify-between ${t.page}`}>
        <div className={`flex w-[${w}px] h-[${headerH}px] items-center justify-between`}>
          <Stat label="Score" t={t} w={statW} h={headerH} font={Math.round(headerH * 0.38)} />
          <Stat label="Best" t={t} w={statW} h={headerH} font={Math.round(headerH * 0.38)} />
          {undoButton(bw, headerH, bFont)}
          {newButton(bw, 'New', headerH, bFont)}
        </div>
        {boardBox}
        <div className={`flex w-[${w}px] justify-between`}>
          {(['left', 'up', 'down', 'right']).map((dir) => arrowButton(dir, aw))}
        </div>
      </div>
    )
  }

  // Stacked: score and best over the board, the arrows and buttons under it.
  const statW = Math.round(Math.min(tall ? 200 : 160, (W - 2 * m) * 0.26))
  const wideButton = Math.round(Math.max(key, (panelW - 4 * key - 5 * 8) / 2))
  const controls = tall ? (
    <div className={`flex flex-col gap-[10px] w-[${boardPx}px]`}>
      <div className="flex justify-between">
        {(['left', 'up', 'down', 'right']).map((dir) => arrowButton(dir, Math.floor((boardPx - 30) / 4)))}
      </div>
      <div className="flex justify-between">
        {undoButton(Math.floor((boardPx - 10) / 2))}
        {newButton(Math.floor((boardPx - 10) / 2), 'New game')}
      </div>
    </div>
  ) : (
    <div className="flex gap-[8px] items-center justify-center">
      {arrowButton('left')}
      {arrowButton('up')}
      {arrowButton('down')}
      {arrowButton('right')}
      {undoButton(wideButton)}
      {newButton(wideButton, 'New')}
    </div>
  )
  return (
    <div className={`flex flex-col w-full h-full p-[${m}px] gap-[${m}px] items-center justify-between ${t.page}`}>
      <div className={`flex w-[${boardPx}px] h-[${headerH}px] items-center justify-between gap-2`}>
        <span className={`text-[${Math.round(headerH * 0.62)}px] font-black leading-none ${t.title}`}>2048</span>
        <div className="flex gap-2">
          <Stat label="Score" t={t} w={statW} h={headerH} font={Math.round(headerH * 0.38)} />
          <Stat label="Best" t={t} w={statW} h={headerH} font={Math.round(headerH * 0.38)} />
        </div>
      </div>
      {boardBox}
      {controls}
    </div>
  )
}

