// The rules of 2048, with no drawing: a board is a flat array of numbers
// (0 = empty), row by row. Everything here is plain values, so a game fits in
// the scene's state as JSON and outlives a restart.

export type Game = {
  size: number
  cells: number[]
  score: number
  best: number
  // A seeded random number generator's state, so a deal is reproducible.
  seed: number
  // The board and score before the last move, for one undo.
  undo: { cells: number[]; score: number } | null
  won: boolean // reached 2048 at some point
  keepPlaying: boolean // the person chose to go on after winning
  moves: number
}

export type Direction = 'left' | 'right' | 'up' | 'down'

/** mulberry32: a small, fast generator whose whole state is one integer. */
export function nextRandom(game: Game): number {
  let t = (game.seed = (game.seed + 0x6d2b79f5) | 0)
  t = Math.imul(t ^ (t >>> 15), t | 1)
  t ^= t + Math.imul(t ^ (t >>> 7), t | 61)
  return ((t ^ (t >>> 14)) >>> 0) / 4294967296
}

/** A new tile (a 2, one time in ten a 4) on a random empty cell. */
export function addTile(game: Game): boolean {
  const empty: number[] = []
  for (let i = 0; i < game.cells.length; i++) if (game.cells[i] === 0) empty.push(i)
  if (!empty.length) return false
  const at = empty[Math.floor(nextRandom(game) * empty.length)]
  game.cells[at] = nextRandom(game) < 0.9 ? 2 : 4
  return true
}

export function newGame(size: number, seed: number, best: number): Game {
  const n = size >= 3 && size <= 8 ? size : 4
  const game: Game = {
    size: n,
    cells: new Array(n * n).fill(0),
    score: 0,
    best: best || 0,
    seed: seed | 0,
    undo: null,
    won: false,
    keepPlaying: false,
    moves: 0,
  }
  addTile(game)
  addTile(game)
  return game
}

/** The cell indexes of each line, in the order its tiles slide (first = the wall). */
function lines(size: number, dir: Direction): number[][] {
  const out: number[][] = []
  for (let a = 0; a < size; a++) {
    const line: number[] = []
    for (let b = 0; b < size; b++) {
      if (dir === 'left') line.push(a * size + b)
      else if (dir === 'right') line.push(a * size + (size - 1 - b))
      else if (dir === 'up') line.push(b * size + a)
      else line.push((size - 1 - b) * size + a)
    }
    out.push(line)
  }
  return out
}

/**
 * Slides every tile towards `dir`, merging equal neighbours once each.
 * Returns the points scored, or -1 when nothing moved. Changes `cells` in place.
 */
export function slide(cells: number[], size: number, dir: Direction): number {
  let points = 0
  let moved = false
  for (const line of lines(size, dir)) {
    const values: number[] = []
    for (const i of line) if (cells[i]) values.push(cells[i])
    const merged: number[] = []
    for (let k = 0; k < values.length; k++) {
      if (k + 1 < values.length && values[k] === values[k + 1]) {
        merged.push(values[k] * 2)
        points += values[k] * 2
        k++
      } else merged.push(values[k])
    }
    for (let k = 0; k < line.length; k++) {
      const value = k < merged.length ? merged[k] : 0
      if (cells[line[k]] !== value) moved = true
      cells[line[k]] = value
    }
  }
  return moved ? points : -1
}

/** Plays a move: true when the board changed (a new tile then appears). */
export function move(game: Game, dir: Direction): boolean {
  if (isOver(game)) return false
  if (game.won && !game.keepPlaying) return false
  const cells = game.cells.slice()
  const points = slide(cells, game.size, dir)
  if (points < 0) return false
  game.undo = { cells: game.cells, score: game.score }
  game.cells = cells
  game.score += points
  if (game.score > game.best) game.best = game.score
  game.moves += 1
  if (!game.won && cells.some((v) => v >= 2048)) game.won = true
  addTile(game)
  return true
}

export function undo(game: Game): boolean {
  if (!game.undo) return false
  game.cells = game.undo.cells
  game.score = game.undo.score
  game.undo = null
  game.moves = Math.max(0, game.moves - 1)
  // Winning stays won: an undo does not take the prize back.
  return true
}

/** No empty cell and no two equal neighbours: no move is left. */
export function isOver(game: Game): boolean {
  const { cells, size } = game
  for (let i = 0; i < cells.length; i++) {
    if (!cells[i]) return false
    const x = i % size
    if (x + 1 < size && cells[i] === cells[i + 1]) return false
    if (i + size < cells.length && cells[i] === cells[i + size]) return false
  }
  return true
}

export function biggest(game: Game): number {
  let top = 0
  for (const v of game.cells) if (v > top) top = v
  return top
}

/** A game read back from state, or null when it is not one (an old shape, nothing yet). */
export function readGame(value: any): Game | null {
  if (!value || typeof value !== 'object' || !Array.isArray(value.cells)) return null
  const size = value.size | 0
  if (size < 3 || size > 8 || value.cells.length !== size * size) return null
  return {
    size,
    cells: value.cells.map((v: any) => Number(v) || 0),
    score: Number(value.score) || 0,
    best: Number(value.best) || 0,
    seed: Number(value.seed) | 0,
    undo: value.undo && Array.isArray(value.undo.cells) && value.undo.cells.length === size * size ? value.undo : null,
    won: !!value.won,
    keepPlaying: !!value.keepPlaying,
    moves: Number(value.moves) || 0,
  }
}
